66	func (a *App) Run(ctx context.Context) error {
67		slog.Info("televibe starting",
68			"provider", a.cfg.AI.Provider,
69			"threshold", a.cfg.Risk.TicketThreshold,
70			"itsm_project", a.cfg.Jira.Project)
71	
72		if err := a.rehydrate(ctx); err != nil {
73			return fmt.Errorf("rehydrate open ITSM tickets: %w", err)
