97		watcher, err := a.tele.NewWatcher(ctx, types.Watch{
98			Kinds: []types.WatchKind{{Kind: types.KindAccessRequest}},
99		})
100		if err != nil {
101			return fmt.Errorf("start watcher: %w", err)
102		}
103		defer watcher.Close()
104	
105		for {
106			select {
107			case <-ctx.Done():
108				return ctx.Err()
109			case <-watcher.Done():
110				return watcher.Error()
111			case ev := <-watcher.Events():
112				if ev.Type != types.OpPut {
113					continue
114				}
115				req, ok := ev.Resource.(types.AccessRequest)
116				if !ok {
117					continue
118				}
119				if req.GetState() != types.RequestState_PENDING {
120					continue
121				}
122				a.pendingMu.Lock()
123				_, held := a.pending[req.GetName()]
124				a.pendingMu.Unlock()
