144			"score", result.Score,
145			"tier", result.Tier.Name,
146			"slang", result.Tier.Slang,
147			"components", result.Components)
148	
149		if result.Score < a.cfg.Risk.TicketThreshold {
150			reason := fmt.Sprintf("televibe: %s (score %d, %q) — auto-approved",
151				result.Tier.Name, result.Score, result.Tier.Slang)
152			if err := a.submitReview(ctx, id, types.RequestState_APPROVED, reason); err != nil {
153				log.Error("auto-approve failed", "err", err)
154			}
155			return
156		}
157	
158		ticket, err := a.jira.CreateITSMTicket(ctx, jira.TicketInput{
159			RequestID:   id,
160			User:        req.GetUser(),
161			Roles:       req.GetRoles(),
162			Reason:      req.GetRequestReason(),
163			Score:       result.Score,
164			Tier:        result.Tier.Name,
165			Slang:       result.Tier.Slang,
166			Components:  result.Components,
167			AIReasoning: result.Reasoning,
168		})
169		if err != nil {
170			log.Error("create ITSM ticket failed", "err", err)
171			return
172		}
173	
174		a.pendingMu.Lock()
175		a.pending[id] = ticket
176		a.pendingMu.Unlock()
177		log.Info("ITSM ticket created, request held for SRE review",
178			"ticket", ticket, "tier", result.Tier.Name, "slang", result.Tier.Slang)
179	}
