package risk

type Config struct {
	TicketThreshold int    `toml:"ticket_threshold"`
	CUSTXPattern    string `toml:"custx_pattern"`
	OffHoursStart   int    `toml:"off_hours_start"`
	OffHoursEnd     int    `toml:"off_hours_end"`
	Timezone        string `toml:"timezone"`
}

func (c *Config) ApplyDefaults() {
	if c.TicketThreshold == 0 {
		c.TicketThreshold = 25
	}
	if c.CUSTXPattern == "" {
		c.CUSTXPattern = `CUSTX-\d+`
	}
	if c.Timezone == "" {
		c.Timezone = "UTC"
	}
}

type Tier struct {
	Name     string
	Slang    string
	MinScore int
}

var Tiers = []Tier{
	{Name: "low", Slang: "no cap", MinScore: 0},
	{Name: "medium", Slang: "sus", MinScore: 25},
	{Name: "high", Slang: "mad sus fr", MinScore: 50},
	{Name: "critical", Slang: "straight L, touch grass", MinScore: 75},
}

func TierForScore(score int) Tier {
	chosen := Tiers[0]
	for _, t := range Tiers {
		if score >= t.MinScore {
			chosen = t
		}
	}
	return chosen
}

