1	package risk
2	
3	import (
4		"context"
5		"regexp"
6		"time"
7	
8		"github.com/gravitational/teleport/api/types"
9	
10		"televibe/ai"
11	)
12	
13	type Result struct {
14		Score      int
15		Tier       Tier
16		Components map[string]int
17		Reasoning  string
18	}
19	
20	type Scorer struct {
21		cfg        Config
22		custxRegex *regexp.Regexp
23		loc        *time.Location
24	}
25	
26	func NewScorer(cfg Config) (*Scorer, error) {
27		re, err := regexp.Compile(cfg.CUSTXPattern)
28		if err != nil {
29			return nil, err
30		}
31		loc, err := time.LoadLocation(cfg.Timezone)
32		if err != nil {
33			return nil, err
34		}
35		return &Scorer{cfg: cfg, custxRegex: re, loc: loc}, nil
36	}
37	
38	func (s *Scorer) Score(ctx context.Context, prov ai.Provider, req types.AccessRequest) (*Result, error) {
39		reason := req.GetRequestReason()
40		hasCUSTX := s.custxRegex.MatchString(reason)
41		descLen := len(reason)
42	
43		var resources []string
44		for _, r := range req.GetRequestedResourceIDs() {
45			resources = append(resources, r.Name)
46		}
47	
48		assessment, err := prov.Assess(ctx, ai.ScoreRequest{
49			User:              req.GetUser(),
50			Roles:             req.GetRoles(),
51			Resources:         resources,
52			Reason:            reason,
53			HasCUSTXReference: hasCUSTX,
54			DescriptionLength: descLen,
55		})
56		if err != nil {
57			return nil, err
