package reputation

import (
	"context"
	"os"
	"path/filepath"
	"testing"
)

func baseCfg(path string) Config {
	c := Config{PersistPath: path, FloorScore: 0}
	c.ApplyDefaults()
	return c
}

func TestScore_DefaultsToStartingScore(t *testing.T) {
	s, err := NewStore(baseCfg(""))
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	if got := s.Score("alice"); got != 100 {
		t.Errorf("Score(alice) = %d, want 100", got)
	}
}

func TestAssess_AppliesConfiguredPenalties(t *testing.T) {
	cfg := baseCfg("")
	cfg.PenaltyMissingCUSTX = 30
	cfg.PenaltyThinDescription = 15
	s, _ := NewStore(cfg)

	a, err := s.Assess(context.Background(), "alice", map[string]int{
		"missing_custx_ticket": 30,
		"thin_description":     15,
		"privilege_concern":    10, // not a reputation signal, ignored
	})
	if err != nil {
		t.Fatalf("Assess: %v", err)
	}
	if a.Previous != 100 {
		t.Errorf("Previous = %d, want 100", a.Previous)
	}
	if a.Score != 55 {
		t.Errorf("Score = %d, want 55", a.Score)
	}
	if len(a.Penalties) != 2 {
		t.Errorf("len(Penalties) = %d, want 2", len(a.Penalties))
	}
}

func TestAssess_ClampsToFloor(t *testing.T) {
	cfg := baseCfg("")
	cfg.PenaltyMissingCUSTX = 40
	s, _ := NewStore(cfg)
	ctx := context.Background()

	for i := 0; i < 5; i++ {
		if _, err := s.Assess(ctx, "alice", map[string]int{"missing_custx_ticket": 1}); err != nil {
			t.Fatalf("Assess: %v", err)
		}
	}
	if got := s.Score("alice"); got != 0 {
		t.Errorf("floored score = %d, want 0", got)
	}
}

func TestAssess_NoSignalsIsNoOp(t *testing.T) {
	s, _ := NewStore(baseCfg(""))
	a, err := s.Assess(context.Background(), "bob", map[string]int{"description_quality": 3})
	if err != nil {
		t.Fatalf("Assess: %v", err)
	}
	if a.Score != 100 || len(a.Penalties) != 0 {
		t.Errorf("unexpected assessment: %+v", a)
	}
}

func TestPersistence_RoundTrip(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "sub", "rep.json") // exercise MkdirAll

	cfg := baseCfg(path)
	cfg.PenaltyMissingCUSTX = 10
	s, err := NewStore(cfg)
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	if _, err := s.Assess(context.Background(), "alice", map[string]int{"missing_custx_ticket": 1}); err != nil {
		t.Fatalf("Assess: %v", err)
	}

	s2, err := NewStore(cfg)
	if err != nil {
		t.Fatalf("NewStore (reload): %v", err)
	}
	if got := s2.Score("alice"); got != 90 {
		t.Errorf("after reload, Score(alice) = %d, want 90", got)
	}
	if got := s2.Score("bob"); got != 100 {
		t.Errorf("unseen user Score(bob) = %d, want 100", got)
	}

	st, err := os.Stat(path)
	if err != nil {
		t.Fatalf("stat: %v", err)
	}
	if got := st.Mode().Perm(); got != 0o600 {
		t.Errorf("mode = %o, want 0600", got)
	}
}

func TestValidate(t *testing.T) {
	cases := []struct {
		name string
		cfg  Config
		ok   bool
	}{
		{"floor_above_ceiling", Config{FloorScore: 50, CeilingScore: 10, StartingScore: 20}, false},
		{"starting_out_of_range", Config{FloorScore: 0, CeilingScore: 100, StartingScore: 150}, false},
		{"ok", Config{FloorScore: 0, CeilingScore: 100, StartingScore: 50}, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			err := tc.cfg.Validate()
			if (err == nil) != tc.ok {
				t.Errorf("Validate() err = %v, ok = %v", err, tc.ok)
			}
		})
	}
}

func TestRange_IteratesAllUsers(t *testing.T) {
	cfg := baseCfg("")
	cfg.PenaltyMissingCUSTX = 10
	cfg.PenaltyThinDescription = 5
	s, _ := NewStore(cfg)
	ctx := context.Background()
	_, _ = s.Assess(ctx, "alice", map[string]int{"missing_custx_ticket": 1})
	_, _ = s.Assess(ctx, "bob", map[string]int{"thin_description": 1})

	seen := map[string]int{}
	s.Range(func(u string, sc int) { seen[u] = sc })
	if len(seen) != 2 {
		t.Errorf("len(seen) = %d, want 2", len(seen))
	}
	if seen["alice"] != 90 || seen["bob"] != 95 {
		t.Errorf("unexpected seen: %+v", seen)
	}
}

func TestAssess_DisabledPenaltyIsSkipped(t *testing.T) {
	cfg := baseCfg("")
	cfg.PenaltyMissingCUSTX = 0 // explicit disable
	cfg.PenaltyThinDescription = 5
	cfg.StartingScore = 100
	// ApplyDefaults already ran in baseCfg, but setting to 0 after is a valid
	// "turn this off" gesture — ApplyDefaults would resurrect it, so rebuild:
	s, _ := NewStore(cfg)

	a, _ := s.Assess(context.Background(), "alice", map[string]int{
		"missing_custx_ticket": 1,
		"thin_description":     1,
	})
	if a.Score != 95 {
		t.Errorf("Score = %d, want 95 (only thin_description applied)", a.Score)
	}
	for _, p := range a.Penalties {
		if p.Reason == "missing_custx_ticket" {
			t.Errorf("missing_custx_ticket penalty should be skipped when amount = 0")
		}
	}
}

