// Package telemetry wires an OpenTelemetry MeterProvider to an OTLP/gRPC
// collector and publishes per-user reputation as an observable gauge. The
// collector is expected to fan out to Datadog (or any other backend) via
// its own exporter pipeline.
package telemetry

import (
	"context"
	"fmt"
	"time"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/exporters/otlp/otlpmetric/otlpmetricgrpc"
	"go.opentelemetry.io/otel/metric"
	sdkmetric "go.opentelemetry.io/otel/sdk/metric"
	"go.opentelemetry.io/otel/sdk/resource"
	semconv "go.opentelemetry.io/otel/semconv/v1.24.0"
)

type Config struct {
	Enabled      bool          `toml:"enabled"`
	Endpoint     string        `toml:"endpoint"`
	Insecure     bool          `toml:"insecure"`
	ServiceName  string        `toml:"service_name"`
	ExportPeriod time.Duration `toml:"export_period"`
}

func (c *Config) ApplyDefaults() {
	if c.ServiceName == "" {
		c.ServiceName = "televibe"
	}
	if c.ExportPeriod == 0 {
		c.ExportPeriod = 15 * time.Second
	}
}

// ReputationSource is the minimum surface telemetry needs from the
// reputation store: iterate the users it currently knows about.
type ReputationSource interface {
	Range(fn func(user string, score int))
}

type Meter struct {
	provider *sdkmetric.MeterProvider
	reg      metric.Registration
}

func New(ctx context.Context, cfg Config, src ReputationSource) (*Meter, error) {
	opts := []otlpmetricgrpc.Option{}
	if cfg.Endpoint != "" {
		opts = append(opts, otlpmetricgrpc.WithEndpoint(cfg.Endpoint))
	}
	if cfg.Insecure {
		opts = append(opts, otlpmetricgrpc.WithInsecure())
	}
	exp, err := otlpmetricgrpc.New(ctx, opts...)
	if err != nil {
		return nil, fmt.Errorf("otlp exporter: %w", err)
	}

	res, err := resource.New(ctx, resource.WithAttributes(semconv.ServiceName(cfg.ServiceName)))
	if err != nil {
		return nil, fmt.Errorf("resource: %w", err)
	}

	provider := sdkmetric.NewMeterProvider(
		sdkmetric.WithResource(res),
		sdkmetric.WithReader(sdkmetric.NewPeriodicReader(exp, sdkmetric.WithInterval(cfg.ExportPeriod))),
	)
	otel.SetMeterProvider(provider)

	meter := provider.Meter("televibe/reputation")
	gauge, err := meter.Int64ObservableGauge(
		"televibe.user.reputation",
		metric.WithDescription("Per-user reputation score (lower = worse)"),
	)
	if err != nil {
		_ = provider.Shutdown(ctx)
		return nil, fmt.Errorf("register gauge: %w", err)
	}

	reg, err := meter.RegisterCallback(func(_ context.Context, o metric.Observer) error {
		src.Range(func(user string, score int) {
			o.ObserveInt64(gauge, int64(score), metric.WithAttributes(
				attribute.String("user", user),
			))
		})
		return nil
	}, gauge)
	if err != nil {
		_ = provider.Shutdown(ctx)
		return nil, fmt.Errorf("register callback: %w", err)
	}

	return &Meter{provider: provider, reg: reg}, nil
}

// Shutdown unregisters the callback and flushes pending metrics to the
// collector. Safe to call on a nil receiver.
func (m *Meter) Shutdown(ctx context.Context) error {
	if m == nil || m.provider == nil {
		return nil
	}
	_ = m.reg.Unregister()
	return m.provider.Shutdown(ctx)
}

